#include <pthread.h>
#include <stdio.h>
#include <time.h>

static void ms_sleep(unsigned ms)
{
    struct timespec ts;
    ts.tv_sec = (time_t)(ms / 1000u);
    ts.tv_nsec = (long)((ms % 1000u) * 1000000u);
    nanosleep(&ts, NULL);
}

static void *worker(void *arg)
{
    (void)arg;
    puts("Hello!");
    return NULL;
}

int main(void)
{
    pthread_t t;
    pthread_create(&t, NULL, worker, NULL);
    ms_sleep(100);
    pthread_join(t, NULL);
    puts("main done");
    return 0;
}

#include <pthread.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

static int g_out;

static void *sender(void *arg)
{
    (void)arg;
    const char *m = "ping";
    write(g_out, m, (int)strlen(m));
    return NULL;
}

int main(void)
{
    int fd[2];
    pipe(fd);
    g_out = fd[1];
    pthread_t th;
    pthread_create(&th, NULL, sender, NULL);
    char buf[16];
    ssize_t n = read(fd[0], buf, sizeof(buf) - 1);
    if (n > 0) {
        buf[n] = '\0';
        fputs(buf, stdout);
    }
    close(fd[0]);
    close(fd[1]);
    pthread_join(th, NULL);
    return 0;
}

