#include <pthread.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

static int g_wr;

static void *producer(void *arg)
{
    (void)arg;
    const char *msg = "1\n2\n3";
    write(g_wr, msg, strlen(msg));
    close(g_wr);
    return NULL;
}

int main(void)
{
    int fd[2];
    pipe(fd);
    g_wr = fd[1];
    pthread_t th;
    pthread_create(&th, NULL, producer, NULL);
    pthread_join(th, NULL);
    char chunk[64];
    ssize_t n;
    while ((n = read(fd[0], chunk, sizeof(chunk))) > 0) {
        fwrite(chunk, 1, (size_t)n, stdout);
    }
    close(fd[0]);
    return 0;
}

#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static pthread_mutex_t mu = PTHREAD_MUTEX_INITIALIZER;
static char *words[2];
static int count;

static void *add_word(void *arg)
{
    const char *w = (const char *)arg;
    pthread_mutex_lock(&mu);
    words[count++] = (char *)w;
    pthread_mutex_unlock(&mu);
    return NULL;
}

static int cmp_str(const void *a, const void *b)
{
    char *const *x = (char *const *)a;
    char *const *y = (char *const *)b;
    return strcmp(*x, *y);
}

int main(void)
{
    pthread_t t1, t2;
    pthread_create(&t1, NULL, add_word, "hello");
    pthread_create(&t2, NULL, add_word, "world");
    pthread_join(t1, NULL);
    pthread_join(t2, NULL);
    qsort(words, 2, sizeof(words[0]), cmp_str);
    puts(words[0]);
    puts(words[1]);
    return 0;
}

