#include <pthread.h>
#include <stdio.h>

static void *print_id(void *arg)
{
    int id = *(int *)arg;
    printf("%d\n", id);
    return NULL;
}

int main(void)
{
    int ids[3] = {1, 2, 3};
    for (int i = 0; i < 3; i++) {
        pthread_t t;
        pthread_create(&t, NULL, print_id, &ids[i]);
        pthread_join(t, NULL);
    }
    puts("done");
    return 0;
}
